// Pick the inventory file: an Excel file (inventory.xlsx) or a Google Sheet (inventory), newest first.
// Throws when the Drive search failed or found nothing, so the sync stops before anything in the product list changes.
const settings = $('Sync Settings').first(0).json;
const want = String(settings.file_name ?? 'inventory.xlsx').trim().toLowerCase().replace(/\.xlsx$/, '');
const XLSX = 'application/vnd.openxmlformats-officedocument.spreadsheetml.sheet';
const SHEET = 'application/vnd.google-apps.spreadsheet';
const errText = e => (typeof e === 'string' ? e : e?.message ?? JSON.stringify(e)).slice(0, 300);
// n8n keeps only the first line of a Code node error, and only the text after its last ":",
// so the messages here are one line and use " - " instead
const plain = s => String(s).replace(/\s+/g, ' ').replace(/\s*:\s*/g, ' - ').replace(/[.\s]+$/, '');

const found = $input.all().map(i => i.json ?? {});
const failed = found.find(f => f.error !== undefined && !f.id);  // Find Excel File passes its error on as an item
if (failed) throw new Error(`Google Drive search failed - ${plain(errText(failed.error))}`);

const files = found
  .filter(f => f.id && !f.trashed && [XLSX, SHEET].includes(f.mimeType))
  .filter(f => [want, `${want}.xlsx`].includes(String(f.name ?? '').trim().toLowerCase()))
  .sort((a, b) => String(b.modifiedTime ?? '').localeCompare(String(a.modifiedTime ?? '')));

if (!files.length) throw new Error(`No Excel file "${want}.xlsx" or Google Sheet "${want}" found in Google Drive`);
const f = files[0];
return [{ json: { id: f.id, name: f.name, mimeType: f.mimeType, modifiedTime: f.modifiedTime ?? '', other_copies: files.length - 1 } }];

// What happened in this run, and should the owner hear about it?
// Email when the sync has failed twice in a row (so a one-off Google Drive hiccup that fixes itself
// stays quiet), when it works again after that email, and when the list of spreadsheet problems changes.
// Never every 5 minutes for the same thing.
const ALERT_AFTER_FAILS = 2;  // failed runs in a row before emailing (runs are 5 minutes apart)
const txt = v => String(v ?? '').trim();
const errText = e => (typeof e === 'string' ? e : e?.message ?? JSON.stringify(e ?? ''))
  .replace(/\s*\[line \d+[^\]]*\]\s*$/, '').trim().slice(0, 500);
const sentence = s => (/[.!?]$/.test(s) ? s : `${s}.`);
const STEPS = ['Pick Inventory File', 'Download File', 'Validate & Clean'];  // the steps with an error output

let last = {};
try { last = $('Load Last Status').first(0)?.json ?? {}; } catch (e) {}
const input = $input.first()?.json ?? {};

let ok, message, problems = [], fileSignature = '', applied = false;
if (input.error) {
  // a step failed before anything changed: find which one
  let step = 'A step';
  for (const s of STEPS) {
    try { if ($(s).isExecuted && $(s).all(1).length) { step = s; break; } } catch (e) {}
  }
  ok = false;
  message = `Inventory sync failed at "${step}": ${sentence(errText(input.error))} The chat keeps using the last good product list.`;
} else {
  const v = $('Validate & Clean').first(0).json;
  problems = v.problems ?? [];
  fileSignature = txt(v.problems_signature);
  if (!v.safe) {
    ok = false;
    message = `Inventory sync blocked, nothing was changed. ${v.reason}`;
  } else {
    applied = true;
    const r = input;  // from Removals Done
    const failures = (r.save_failed ?? 0) + (r.delete_failed ?? 0);
    ok = failures === 0;
    message = `Synced ${v.products_in_file} products: ${r.saved ?? 0} added or updated, ${r.deleted ?? 0} removed.`
      + (failures ? ` ${failures} change(s) could not be saved and will be retried on the next sync.` : '')
      + (problems.length ? ` ${problems.length} row(s) in the spreadsheet need fixing.` : '');
  }
}

const fails = ok ? 0 : (Number(last.fails) || 0) + 1;
const wasAlerted = last.down_alerted === true;
const broke = !ok && !wasAlerted && fails >= ALERT_AFTER_FAILS;
const recovered = ok && wasAlerted;
const down_alerted = !ok && (wasAlerted || broke);
// Row problems are only news when the file was applied; a failed or blocked run keeps the last known list.
const signature = applied ? fileSignature : txt(last.problems_signature);
const newProblems = applied && signature !== '' && signature !== txt(last.problems_signature);
const alert = broke || recovered || newProblems;

const lines = problems.slice(0, 25).map(p => `- ${p.product}: ${p.issue} (${p.action})`);
const detail = [message, lines.length ? `\nRows to fix in the spreadsheet:\n${lines.join('\n')}` : ''].join('\n').trim();
const subject = !alert ? ''
  : broke ? 'Inventory sync stopped'
  : recovered ? 'Inventory sync works again'
  : `Spreadsheet rows need fixing: ${problems[0]?.product ?? ''}${problems.length > 1 ? ` and ${problems.length - 1} more` : ''}`;

return [{ json: {
  ok, fails, down_alerted, message: message.slice(0, 1000), problems_signature: signature.slice(0, 4000),
  alert, alert_subject: subject.slice(0, 200), alert_detail: detail.slice(0, 4000),
} }];

// Validate & Clean: checks every Excel row and works out what to change in the product list.
// In:  one item per Excel row (from Read Excel Rows) + the current products (from Read Current Products)
// Out: ONE item: { safe, reason, upserts[], removed[], problems[] }
const FIELDS = ['sku', 'name', 'category', 'price_ex_vat', 'stock_qty', 'image_url', 'description', 'tags'];
const REQUIRED = ['sku', 'name', 'category', 'price_ex_vat', 'stock_qty'];
const CATEGORIES = ['mouse', 'keyboard', 'headset', 'monitor', 'webcam', 'mousepad', 'speaker', 'accessory'];
// Refuse to sync when a file suddenly has far fewer valid products than the store has now
// (wrong file or sheet, rows deleted by mistake). Set allow_big_changes in Sync Settings to accept it once.
const MIN_KEEP_SHARE = 0.3;
const settings = $('Sync Settings').first(0)?.json ?? {};
const allowBigChanges = settings.allow_big_changes === true;

const key = k => String(k).trim().toLowerCase().replace(/[\s-]+/g, '_');
const txt = v => String(v ?? '').trim();
const num = v => (typeof v === 'number' ? v
  : txt(v) === '' ? NaN : Number(txt(v).replace(/บาท|thb|฿|,|\s/gi, '')));
const same = (a, b) => FIELDS.every(f => String(a[f] ?? '') === String(b[f] ?? ''));

// Read Current Products and Read Excel Rows pass a failure on as an item like { error: '...' }
const isError = j => j.error !== undefined && Object.keys(j).every(k => ['error', 'message', 'details'].includes(k));
const errText = e => (typeof e === 'string' ? e : e?.message ?? JSON.stringify(e)).slice(0, 300);
// n8n keeps only the first line of a Code node error, and only the text after its last ":",
// so the messages here are one line and use " - " instead
const plain = s => String(s).replace(/\s+/g, ' ').replace(/\s*:\s*/g, ' - ').replace(/[.\s]+$/, '');

// last good copy of every product (the Data table); a single empty item means the table is empty
const current = $('Read Current Products').all(0).map(i => i.json ?? {});
const readFail = current.find(isError);
if (readFail) throw new Error(`Could not read the store's product list - ${plain(errText(readFail.error))}`);
if (current.some(j => Object.keys(j).length && !('sku' in j))) throw new Error("Could not read the store's product list - unexpected data");
const cache = new Map(current.filter(j => j.sku).map(j => [j.sku, j]));

// Excel rows, header names normalised ("Stock Qty" -> "stock_qty")
const excel = $input.all().map(i => i.json ?? {});
const fileFail = excel.find(isError);
if (fileFail) throw new Error(`Could not read the Excel file - ${plain(errText(fileFail.error))}`);
const rows = excel.map(j => Object.fromEntries(Object.entries(j).map(([k, v]) => [key(k), v])));
if (!rows.some(r => Object.keys(r).length)) throw new Error('The Inventory sheet has no rows');
const headers = new Set(rows.flatMap(r => Object.keys(r)));
const missing = REQUIRED.filter(h => !headers.has(h));
if (missing.length) throw new Error(`The Inventory sheet is missing column(s) ${missing.join(', ')}`);

const upserts = [], problems = [], inFile = new Set();
let valid = 0, prevSku = '';
rows.forEach(r => {
  if (FIELDS.every(f => txt(r[f]) === '')) return; // empty line
  const sku = txt(r.sku).toUpperCase();            // SKUs are stored in upper case
  // blank lines are dropped before this node, so name the product instead of an Excel row number
  const product = sku ? `${sku} (${txt(r.name) || 'no name'})`
    : txt(r.name) ? `"${txt(r.name)}" (no sku)` : `the row after ${prevSku || 'the header'}`;
  if (sku) prevSku = sku;
  const p = {
    sku,
    name: txt(r.name),
    category: txt(r.category).toLowerCase(),
    price_ex_vat: Math.round(num(r.price_ex_vat) * 100) / 100,
    stock_qty: num(r.stock_qty),
    image_url: txt(r.image_url),
    description: txt(r.description).slice(0, 1000),
    tags: txt(r.tags).toLowerCase(),
  };

  if (sku && inFile.has(sku)) {
    problems.push({ product, issue: 'duplicate sku', action: 'ignored (the first row with this sku is used)' });
    return;
  }
  if (sku) inFile.add(sku); // present in the file → never removed, even if this row has mistakes

  const errors = [];
  if (!sku) errors.push('sku is empty');
  if (!p.name) errors.push('name is empty');
  if (!p.category) errors.push('category is empty');
  if (!Number.isFinite(p.price_ex_vat) || p.price_ex_vat < 0) errors.push(`price_ex_vat "${txt(r.price_ex_vat)}" is not a valid price`);
  if (!Number.isInteger(p.stock_qty) || p.stock_qty < 0) errors.push(`stock_qty "${txt(r.stock_qty)}" is not a whole number >= 0`);
  if (errors.length) {
    problems.push({ product, issue: errors.join('; '),
                    action: cache.has(sku) ? 'kept the last good version' : 'not added' });
    return;
  }

  // warnings: the row is still saved
  if (!CATEGORIES.includes(p.category)) problems.push({ product, issue: `unknown category "${p.category}"`, action: 'saved' });
  if (p.image_url && !/^https?:\/\//i.test(p.image_url)) {
    problems.push({ product, issue: 'image_url is not a link', action: 'saved without image' });
    p.image_url = '';
  }

  valid++;
  const old = cache.get(sku);
  if (!old || !same(old, p)) upserts.push(p); // only new or changed products are written
});

const removed = [...cache.keys()].filter(sku => !inFile.has(sku));
const shrinks = cache.size >= 10 && valid < cache.size * MIN_KEEP_SHARE;
const safe = valid > 0 && (!shrinks || allowBigChanges);
const reason = valid === 0 ? 'No valid products in the file'
  : !safe ? `The file has only ${valid} valid products, but the store has ${cache.size}. Wrong file or sheet? `
    + 'If this is right, set allow_big_changes to true in Sync Settings, run the sync once, then set it back to false.'
  : '';

return [{ json: {
  safe, reason,
  upserts,
  removed: removed.map(sku => ({ sku })),
  problems,
  problems_signature: problems.map(p => `${p.product}: ${p.issue}`).join('\n'),
  products_in_file: valid,
  products_before: cache.size,
} }];

// Count what Save Product did (it reports a failed row as an item with an error instead of stopping).
// A failed row is simply tried again by the next sync.
let saved = 0;
const failed = [];
if ($('Save Product').isExecuted) {
  for (const i of $('Save Product').all(0)) {
    if (i.json?.error) failed.push(String(i.json.error?.message ?? i.json.error));
    else if (i.json?.sku) saved++;
  }
}
return [{ json: { saved, save_failures: failed.slice(0, 10), save_failed: failed.length } }];

// One item per product that is no longer in the file, for Delete Product. Never an empty SKU.
return $('Validate & Clean').first(0).json.removed
  .filter(r => r && String(r.sku ?? '').trim())
  .map(r => ({ json: { sku: String(r.sku).trim() } }));

// Count what Delete Product did. A failed delete is simply tried again by the next sync.
let deleted = 0;
const failed = [];
if ($('Delete Product').isExecuted) {
  for (const i of $('Delete Product').all(0)) {
    if (i.json?.error) failed.push(String(i.json.error?.message ?? i.json.error));
    else if (i.json?.sku) deleted++;  // an empty item means the product was already gone
  }
}
const saves = $('Saves Done').first(0)?.json ?? { saved: 0, save_failed: 0, save_failures: [] };
return [{ json: { ...saves, deleted, delete_failures: failed.slice(0, 10), delete_failed: failed.length } }];

// The alert for the Error Handler: it logs it and emails the owner.
// always_email: this workflow already decides when to email, so the Error Handler must not hold it back.
const r = $('Record Result').first(0).json;
return [{ json: { workflow_name: 'Inventory Sync', message: r.alert_subject, detail: r.alert_detail, always_email: true } }];
